def _truthy(val):
    """Return True for common truthy values (bool True, 'true', '1', 1)."""
    if isinstance(val, bool):
        return val
    if val is None:
        return False
    try:
        s = str(val).strip().lower()
    except Exception:
        return False
    return s in {"true", "1", "yes", "y"}


